SourceCode.Declaration:
[DataContractAttribute]
class HSMobileOpsJournalSummaryRow
{
    InventJournalId     journalId;
    InventJournalNameId journalNameId;
    Description          description;
    TransDate            journalDate;
    int                  lineCount;

}

Method.Source:
[DataMemberAttribute('JournalId')]
public InventJournalId parmJournalId(InventJournalId _value = journalId)
{
    journalId = _value;
    return journalId;
}

[DataMemberAttribute('JournalNameId')]
public InventJournalNameId parmJournalNameId(InventJournalNameId _value = journalNameId)
{
    journalNameId = _value;
    return journalNameId;
}

[DataMemberAttribute('Description')]
public Description parmDescription(Description _value = description)
{
    description = _value;
    return description;
}

[DataMemberAttribute('JournalDate')]
public TransDate parmJournalDate(TransDate _value = journalDate)
{
    journalDate = _value;
    return journalDate;
}

/// <summary>
/// Line count only - never the lines themselves. This row powers the list screen; a journal's
/// lines are fetched separately, in bulk, once the worker actually opens it (see
/// HSMobileOpsCountingService's own class doc for why that split exists).
/// </summary>
[DataMemberAttribute('LineCount')]
public int parmLineCount(int _value = lineCount)
{
    lineCount = _value;
    return lineCount;
}
